/**
 * SignCell — the token frame: the Heyting algebra between tokens, and what tokens inherit.
 *
 * Specialization is measured, never declared. A cell (special, specializes, general) told for says that
 * whatever specializes `special` specializes `general`; told against, it denies that. The order is the
 * least preorder containing what is told: the reflexive and transitive closure of the cells' for-sides.
 * Denial is read only where it is said. A denied cell whose pair a told path also reaches is contested
 * (⊤) and reported with that path; a denial never removes a told path, because a record only grows
 * (Obsmetrologia L4, L6). Two tokens that each specialize the other are identified: they stand in the
 * same relations, so they are one point of the frame (relationality R2).
 *
 * The opens of the frame are extents: sets of tokens closed downward under specialization. They form a
 * complete Heyting algebra, the Alexandrov frame of the preorder. Meet is intersection, join is union,
 * U ⇒ V is the largest extent whose meet with U lies in V, {x : ↓x ∩ U ⊆ V}, and ¬U is U ⇒ ∅. The
 * algebra is not Boolean: U ∨ ¬U misses every token with specializations both inside and outside U.
 * A token's own extent ↓t is its principal open, and t specializes u exactly when ↓t ⊆ ↓u.
 *
 * Tellings are inherited along the order. Whatever is told of a token is told of every token that
 * specializes it: the telling of (p, o) at t is the knowledge join of the tellings of (g, p, o) over every
 * generalization g of t, t included. This is the knowledge existential ∃ᵏ along specialization in the
 * subject position (predication P3); the object position is reached through the converse generator.
 * When the generalizations disagree, one telling for and another against, the inherited cell is
 * contested (⊤). The contradiction is held and reported with the generalizations on each side, never
 * resolved by which one is nearer. That report is the obstruction to gluing the tellings over the
 * cover of generalizations.
 *
 * A frame is a pure function of its cells, so frames federate by joining cell bodies: the frame of two
 * bodies together does not depend on the order they are given in (predication P8).
 */
import { address, cell, cellSet, coincidenceKey, coincides, evidenceOf, merge, sidesOf } from "./cell.mjs";
import { readingOfSides } from "@red-cup-engineering/computer-data-engineering-services-section/four";

/** The predicate that tells specialization: (special, specializes, general). */
export const SPECIALIZES = "specializes";

const FRAME = "signcell.token-frame";
const INHERITED = "signcell.inherited-tellings";
const state = new WeakMap();

const byKey = (left, right) => (left < right ? -1 : left > right ? 1 : 0);
const frozen = (values) => Object.freeze([...values]);

function stateOf(frame) {
  const known = state.get(frame);
  if (known === undefined) throw new TypeError("signcell: a token frame must be made by tokenFrame");
  return known;
}

// Every key reachable from `start` along `edges`, `start` included.
function reach(start, edges) {
  const seen = new Set([start]);
  const pending = [start];
  while (pending.length > 0) {
    for (const next of edges.get(pending.pop())?.keys() ?? []) {
      if (!seen.has(next)) { seen.add(next); pending.push(next); }
    }
  }
  return seen;
}

// One told path of cells from `from` to `to`, shortest first.
function toldPath(from, to, told) {
  const parent = new Map([[from, null]]);
  const queue = [from];
  while (queue.length > 0) {
    const at = queue.shift();
    if (at === to) break;
    for (const [next, edge] of told.get(at) ?? []) {
      if (!parent.has(next)) { parent.set(next, [at, edge]); queue.push(next); }
    }
  }
  const path = [];
  for (let at = to; parent.get(at) !== null; at = parent.get(at)[0]) path.unshift(parent.get(at)[1]);
  return frozen(path);
}

const addEdge = (edges, from, to, value) => {
  if (!edges.has(from)) edges.set(from, new Map());
  edges.get(from).set(to, value);
};

/**
 * The token frame of a body of cells. Cells whose predicate is `predicate` (by default `SPECIALIZES`)
 * tell the order; every other cell is a telling of its subject. Its tokens are the order's endpoints
 * and the tellings' subjects.
 */
export function tokenFrame(cells = [], { predicate = SPECIALIZES } = {}) {
  const body = cellSet(cells);
  const tokenOf = new Map();
  const told = new Map();
  const denied = new Map();
  const tellings = new Map();
  const keep = (token) => { const key = coincidenceKey(token); if (!tokenOf.has(key)) tokenOf.set(key, token); return key; };
  for (const at of body) {
    const subject = keep(at.subject);
    if (!coincides(at.predicate, predicate)) {
      if (!tellings.has(subject)) tellings.set(subject, []);
      tellings.get(subject).push(at);
      continue;
    }
    const object = keep(at.object);
    const [toldFor, toldAgainst] = sidesOf(at);
    if (toldFor) addEdge(told, subject, object, at);
    if (toldAgainst) addEdge(denied, subject, object, at);
  }
  const keys = [...tokenOf.keys()].sort(byKey);
  const up = new Map(keys.map((key) => [key, reach(key, told)]));
  const down = new Map(keys.map((key) => [key, new Set()]));
  for (const [key, generalizations] of up) for (const general of generalizations) down.get(general).add(key);
  const tokens = (set) => frozen([...set].sort(byKey).map((key) => tokenOf.get(key)));

  const classes = new Map();
  for (const key of keys) {
    const members = [...up.get(key)].filter((other) => up.get(other).has(key)).sort(byKey);
    if (members.length > 1) classes.set(members[0], members);
  }
  const contested = [];
  for (const [special, generals] of denied) {
    for (const [general, denial] of generals) {
      if (up.get(special).has(general)) contested.push(Object.freeze({ special: tokenOf.get(special), general: tokenOf.get(general), denial, path: toldPath(special, general, told) }));
    }
  }

  const frame = Object.freeze({
    kind: FRAME,
    predicate,
    cells: body,
    tokens: tokens(keys),
    identified: frozen([...classes.values()].map(tokens)),
    contested: frozen(contested),
  });
  state.set(frame, { tokenOf, up, down, denied, tellings, tokens });
  return frame;
}

const keyIn = (inner, token) => {
  const key = coincidenceKey(token);
  if (!inner.tokenOf.has(key)) throw new TypeError(`signcell: ${JSON.stringify(token)} is not a token of this frame`);
  return key;
};

// The keys of an open, refusing tokens outside the frame and sets that are not closed downward.
function openKeys(inner, open) {
  const keys = new Set(open.map((token) => keyIn(inner, token)));
  for (const key of keys) {
    for (const special of inner.down.get(key)) {
      if (!keys.has(special)) throw new TypeError(`signcell: an open must hold every specialization of its tokens; ${JSON.stringify(inner.tokenOf.get(special))} is missing`);
    }
  }
  return keys;
}

/** Whether `special` specializes `general` on the told side of the closure (contested pairs included). */
export function specializes(frame, special, general) {
  const inner = stateOf(frame);
  const key = coincidenceKey(special);
  return inner.up.has(key) ? inner.up.get(key).has(coincidenceKey(general)) : coincides(special, general);
}

/** The FOUR reading of "`special` specializes `general`": told by the closure, denied where a cell denies it. */
export function specialization(frame, special, general) {
  const inner = stateOf(frame);
  const [from, to] = [coincidenceKey(special), coincidenceKey(general)];
  return readingOfSides("knowledge", specializes(frame, special, general), inner.denied.get(from)?.has(to) ?? false);
}

/** The tokens `token` specializes, itself included: the cover its tellings are inherited from. */
export const generalizations = (frame, token) => { const inner = stateOf(frame); return inner.tokens(inner.up.get(keyIn(inner, token))); };

/** The extent of the given tokens: every token that specializes one of them. With one token, its principal open. */
export function extent(frame, ...given) {
  const inner = stateOf(frame);
  const keys = new Set();
  for (const token of given) for (const special of inner.down.get(keyIn(inner, token))) keys.add(special);
  return inner.tokens(keys);
}

/** The top open: every token. */
export const top = (frame) => stateOf(frame).tokens(stateOf(frame).up.keys());
/** The bottom open: no token. */
export const bottom = () => frozen([]);
/** Whether one open lies within another (the frame's order). */
export function within(frame, left, right) {
  const inner = stateOf(frame);
  const container = openKeys(inner, right);
  return [...openKeys(inner, left)].every((key) => container.has(key));
}
/** The meet of opens: the tokens in all of them (the top open when none is given). */
export function meet(frame, ...opens) {
  const inner = stateOf(frame);
  const sets = opens.map((open) => openKeys(inner, open));
  return inner.tokens([...inner.up.keys()].filter((key) => sets.every((set) => set.has(key))));
}
/** The join of opens: the tokens in any of them. */
export function join(frame, ...opens) {
  const inner = stateOf(frame);
  const keys = new Set();
  for (const open of opens) for (const key of openKeys(inner, open)) keys.add(key);
  return inner.tokens(keys);
}
/** Heyting implication U ⇒ V: the tokens whose every specialization in U is in V. */
export function implies(frame, antecedent, consequent) {
  const inner = stateOf(frame);
  const [left, right] = [openKeys(inner, antecedent), openKeys(inner, consequent)];
  return inner.tokens([...inner.up.keys()].filter((key) => [...inner.down.get(key)].every((special) => !left.has(special) || right.has(special))));
}
/** Heyting negation ¬U = U ⇒ ∅: the tokens none of whose specializations is in U. */
export const negation = (frame, open) => implies(frame, open, bottom());

/**
 * What is told of `token`, inherited from every generalization. Each cell is (token, p, o) with the
 * knowledge join of the evidence told of (g, p, o) over the generalizations g; `sources` lists, per
 * cell, the generalizations that told it and their cells; `contested` lists the cells whose inherited
 * evidence is told both for and against, with the generalizations on each side.
 */
export function inherited(frame, token) {
  const inner = stateOf(frame);
  const key = coincidenceKey(token);
  const cover = inner.up.get(key) ?? new Set([key]);
  const merged = new Map();
  const from = new Map();
  for (const general of [...cover].sort(byKey)) {
    for (const telling of inner.tellings.get(general) ?? []) {
      const at = cell(token, telling.predicate, telling.object, evidenceOf(telling));
      const slot = address(at);
      merged.set(slot, merged.has(slot) ? merge(merged.get(slot), at) : at);
      if (!from.has(slot)) from.set(slot, []);
      from.get(slot).push(Object.freeze({ token: inner.tokenOf.get(general), cell: telling }));
    }
  }
  const slots = [...merged.keys()].sort(byKey);
  const cells = frozen(slots.map((slot) => merged.get(slot)));
  const sources = frozen(slots.map((slot) => frozen(from.get(slot))));
  const contested = [];
  slots.forEach((slot, index) => {
    const [toldFor, toldAgainst] = sidesOf(cells[index]);
    if (!(toldFor && toldAgainst)) return;
    const side = (which) => frozen(sources[index].filter((source) => sidesOf(source.cell)[which]).map((source) => source.token));
    contested.push(Object.freeze({ cell: cells[index], for: side(0), against: side(1) }));
  });
  return Object.freeze({ kind: INHERITED, token, cells, sources, contested: frozen(contested) });
}
